-- ============================================
-- LUMA — Thème 16 : MOYEN 3/3 x4 — Une panne au milieu de l'Outback
-- ============================================


update scenarios set content = '{"characters": {"driver": "le conducteur"}, "start_node": "n1", "nodes": {"n1": {"speaker": "you_thought", "text": "(Your van sputters and dies on a remote dirt road, no phone signal in sight.)", "text_fr": "(Votre van tousse et s''arrête sur une route de terre isolée, aucun signal téléphonique en vue.)", "choices": [{"text": "(Check under the hood to see if the problem is obvious.)", "text_fr": "(Vérifie sous le capot pour voir si le problème est évident.)", "next": "n2"}, {"text": "(Wait by the road, hoping another vehicle passes soon.)", "text_fr": "(Attends au bord de la route, en espérant qu''un autre véhicule passe bientôt.)", "next": "n2b"}]}, "n2": {"speaker": "you_thought", "text": "(Nothing looks obviously wrong, but the engine won''t turn over at all.)", "text_fr": "(Rien ne semble évidemment cassé, mais le moteur veut pas du tout démarrer.)", "choices": [{"text": "(Wait for help, since there''s nothing more you can do alone.)", "text_fr": "(Attends de l''aide, puisqu''il n''y a rien de plus que tu puisses faire seul.)", "next": "n3"}]}, "n2b": {"speaker": "you_thought", "text": "(After twenty tense minutes, a dusty ute finally appears in the distance.)", "text_fr": "(Après vingt minutes tendues, un pick-up poussiéreux apparaît enfin au loin.)", "choices": [{"text": "(Wave them down for help.)", "text_fr": "(Fais signe pour demander de l''aide.)", "next": "n3"}]}, "n3": {"speaker": "driver", "text": "G''day, you right there? Saw you from way back, figured you might need a hand.", "text_fr": "Salut, ça va là ? Je vous ai vu de loin, j''ai pensé que vous auriez peut-être besoin d''aide.", "choices": [{"text": "Yeah, my van just died, no idea what''s wrong with it.", "text_fr": "Ouais, mon van vient de mourir, aucune idée de ce qui va pas.", "next": "n4"}]}, "n4": {"speaker": "driver", "text": "Let''s have a look then. Out here, breakdowns happen more than you''d think.", "text_fr": "Voyons voir alors. Par ici, les pannes arrivent plus qu''on pense.", "choices": [{"text": "(Watch as the driver inspects the engine with practiced ease.)", "text_fr": "(Regarde le conducteur inspecter le moteur avec une aisance rodée.)", "next": "n5"}]}, "n5": {"speaker": "driver", "text": "Ah, there''s your problem — a loose connection on the battery. Easy fix.", "text_fr": "Ah, voilà votre problème — une connexion desserrée sur la batterie. Facile à réparer.", "choices": [{"text": "That''s such a relief! Thank you so much for stopping.", "text_fr": "Ça soulage tellement ! Merci beaucoup de vous être arrêté.", "next": "n6"}]}, "n6": {"speaker": "driver", "text": "No worries at all, we look out for each other out here.", "text_fr": "Aucun souci, on veille les uns sur les autres par ici.", "choices": [{"text": "That''s a really beautiful way to think about it, honestly.", "text_fr": "C''est une très belle façon d''y penser, honnêtement.", "next": "n7"}]}, "n7": {"speaker": "driver", "text": "Just how it is in the Outback. Try starting her up now.", "text_fr": "C''est juste comme ça dans l''Outback. Essayez de la démarrer maintenant.", "choices": [{"text": "(Turn the key, relieved to hear the engine roar back to life.)", "text_fr": "(Tourne la clé, soulagé d''entendre le moteur reprendre vie.)", "next": "n8"}]}, "n8": {"speaker": "driver", "text": "There you go! You should be right to continue on now.", "text_fr": "Voilà ! Vous devriez être bon pour continuer maintenant.", "choices": [{"text": "Thank you again, I really don''t know what I would''ve done otherwise.", "text_fr": "Merci encore, je sais vraiment pas ce que j''aurais fait sinon.", "next": "end_helped"}]}, "end_helped": {"speaker": "driver", "text": "All part of the Outback experience, mate. Safe travels!", "text_fr": "Ça fait partie de l''expérience de l''Outback. Bonne route !", "end": true, "ending_label": "Panne dans l''Outback résolue grâce à un local 🚙🇦🇺"}}}'::jsonb, is_playable = true
where title = 'Une panne au milieu de l''''Outback'
  and theme_id = (select id from scenario_themes where position = 16 and language_id = (select id from languages where code = 'en'));
